def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    segments = set()
    directions = {}
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) == abs(dc):
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                slope = 1 if dr * dc > 0 else -1
                for k in range(abs(dr) + 1):
                    pos = (r1 + k * sr, c1 + k * sc)
                    segments.add(pos)
                    directions.setdefault(pos, set()).add(slope)
    for r, c in segments:
        if grid[r][c] == background:
            out[r][c] = 1
    for r, c in sixes:
        for slope in directions.get((r, c), ()):
            for rr in range(h):
                cc = c - slope * (rr - r)
                if 0 <= cc < w and grid[rr][cc] != 1:
                    out[rr][cc] = 6
    return out
